function setupXHRTracking(page, xhrMetrics = []) {
  page.on('requestfinished', async (request) => {
    const url = request.url();
    if (
      url.includes('admin-ajax.php') ||
      url.includes('/wp-json/') ||
      url.includes('acf/validate_save_post')
