  md.push(`- Actual result: [describe]`);
  md.push('');
  if (screenshots.length) {
    md.push('Screenshots:');
    screenshots.forEach(s => md.push(`- ${s}`));
    md.push('');
  }
  if (notes) md.push('Notes:\n' + notes);

  fs.writeFileSync(path.join(evidenceDir, `${evidId}.md`), md.join('\n'));
