  { key: 'lesson', files: ['lesson_sample-lesson.png'] },
  { key: 'ticket', files: ['tickets_page.png','tickets_filled.png','tickets_after_submit.png'] },
  { key: 'grades', files: ['grades.png'] }
];

// Process single flows
for (const map of mapping) {
