        slowXHRCount: slowXHRs.length,
        modalStatus,
        modalContentStatus,
        timestamp: new Date().toISOString(),
      });
    }

  } catch (err) {
    console.warn('⚠️ Ticket flow failed:', err.message);
  }
};
