const loginFlow = require('./flows/loginFlow');
const coursePageFlow = require('./flows/coursePageFlow');
const lessonPageFlow = require('./flows/lessonPageFlow');
const ticketFlow = require('./flows/ticketFlow');
const gradesFlow = require('./flows/gradesFlow');

async function runAll(creds) {
  const outputDir = path.join(__dirname, 'output');
  if (!fs.existsSync(outputDir)) fs.mkdirSync(outputDir, { recursive: true });

  const browser = await puppeteer.launch({ headless: false, args: ['--no-sandbox'] });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 800 });
  const har = new PuppeteerHar(page);
  await har.start({ path: path.join(outputDir, 'run.har') });

  try {
    const results = {};
    results.login = await loginFlow(page, outputDir, creds);
    // Use COURSE_SLUGS env var or default
    const slugs = (process.env.COURSE_SLUGS || 'course-small,course-medium,course-large').split(',').map(s=>s.trim());
    results.courses = [];
    for(const slug of slugs) {
      results.courses.push(await coursePageFlow(page, outputDir, creds, slug));
    }
    results.lesson = await lessonPageFlow(page, outputDir, creds, (process.env.LESSON_SLUG || 'sample-lesson'));
    results.ticket = await ticketFlow(page, outputDir, creds);
    results.grades = await gradesFlow(page, outputDir, creds);
    await har.stop();
    await browser.close();
    fs.writeFileSync(path.join(outputDir, 'results.json'), JSON.stringify(results, null, 2));
    console.log('Done. Outputs in', outputDir);
  } catch (err) {
    console.error('Orchestrator error', err);
    await har.stop();
    await browser.close();
  }
}

if (require.main === module) {
