        xhrMetrics.push({
          url,
          method: request.method(),
          status: response.status(),
          duration,
        });
        if (duration > 500) {
          console.warn(`🐢 Slow XHR [${request.method()}] ${url} → ${Math.round(duration)}ms`);
        }
      } catch (err) {
        console.warn(`⚠️ Could not get XHR timing for ${url}:`, err.message);
      }
    }
  });
}

