  await page.type('input[name="acf[field_65f060dba4ade]"]', 'בדיקת מערכת - כותרת');

  // 4. WYSIWYG (TinyMCE) field
  const content = `בדיקה טכנית - לוודא קליטה תקינה.
זהו שורה שניה.
