module.exports = async function loginFlow(page, outputDir, creds = {}) {
  // creds.url, creds.email, creds.password expected
  const loginUrl = (creds.url || process.env.STAGING_URL || '').replace(/\/+$/, '') + '/custom-login/';
  const waitMs = parseInt(process.env.LOGIN_WAIT_MS || '8000', 10);
  try {
    console.log('[loginFlow] going to', loginUrl);
    await page.goto(loginUrl, { waitUntil: 'domcontentloaded', timeout: 30000 });
    await page.screenshot({ path: `${outputDir}/login_page.png` }).catch(()=>{});

    // try multiple common login fields
    const userSelectors = ['input[name="log"]', 'input#user_login', 'input[name="email"]', 'input[type="email"]'];
    const passSelectors = ['input[name="pwd"]', 'input#user_pass', 'input[name="password"]', 'input[type="password"]'];
    let typedUser = false, typedPass = false;
    for (const s of userSelectors) {
      try {
        if (await page.$(s)) {
          await page.click(s, { clickCount: 3 }).catch(()=>{});
          await page.type(s, creds.email, { delay: 30 });
          typedUser = true;
          console.log('[loginFlow] typed user using', s);
          break;
        }
      } catch (e) { /* ignore */ }
    }
    for (const s of passSelectors) {
      try {
        if (await page.$(s)) {
          await page.click(s, { clickCount: 3 }).catch(()=>{});
          await page.type(s, creds.password, { delay: 30 });
          typedPass = true;
          console.log('[loginFlow] typed pass using', s);
          break;
        }
      } catch (e) { /* ignore */ }
    }

    // submit via form button or enter key
    const submitButtons = ['button[type="submit"]', 'input[type="submit"]', '#wp-submit', 'button[name="login"]', 'button'];
    let clicked = false;
    for (const sel of submitButtons) {
      try {
        const btn = await page.$(sel);
        if (btn) { await btn.click().catch(()=>{}); clicked = true; console.log('[loginFlow] clicked', sel); break; }
      } catch (e) { /* ignore */ }
    }
    if (!clicked) {
      // fallback: press Enter in password field
      try { await page.keyboard.press('Enter'); } catch (e) {}
    }

    // Wait for a robust logged-in signal. Prioritize selectors that indicate a logged in user.
    const loggedInSelectors = [
      'body.logged-in',         // common WP class
      '.bb-profile',            // BuddyBoss profile indicator
      '.bb-user-avatar',        // BuddyBoss avatar
      '.logout',                // visible logout link/button
      '#bp-login'               // fallback
    ];

    const start = Date.now();
    let loggedIn = false;
    while (Date.now() - start < waitMs) {
      for (const sel of loggedInSelectors) {
        try {
          if (await page.$(sel)) { loggedIn = true; console.log('[loginFlow] detected logged-in selector', sel); break; }
        } catch (e) {}
      }
      if (loggedIn) break;
      // Also check for URL change away from login page (common after successful login)
      const curr = page.url();
      if (!curr.includes('/custom-login') && !curr.includes('/wp-login.php')) { loggedIn = true; console.log('[loginFlow] detected URL change to', curr); break; }
      await page.waitForTimeout(500);
    }

    await page.screenshot({ path: `${outputDir}/after_login.png` }).catch(()=>{});
    if (!loggedIn) {
      console.warn('[loginFlow] did not detect logged-in state within', waitMs, 'ms');
      // continue but report non-ok so orchestrator can decide
      return { ok: false, error: 'login timeout', meta: { typedUser, typedPass } };
    }

    return { ok: true };
  } catch (err) {
    await page.screenshot({ path: `${outputDir}/login_error.png` }).catch(()=>{});
    return { ok: false, error: err.message };
  }
}

