    const passSelectors = ['input[name="pwd"]', 'input#user_pass', 'input[name="password"]', 'input[type="password"]'];
    let typedUser = false, typedPass = false;
    for (const s of userSelectors) {
      try {
        if (await page.$(s)) {
          await page.click(s, { clickCount: 3 }).catch(()=>{});
          await page.type(s, creds.email, { delay: 30 });
          typedUser = true;
          console.log('[loginFlow] typed user using', s);
          break;
        }
      } catch (e) { /* ignore */ }
    }
    for (const s of passSelectors) {
      try {
        if (await page.$(s)) {
          await page.click(s, { clickCount: 3 }).catch(()=>{});
          await page.type(s, creds.password, { delay: 30 });
          typedPass = true;
          console.log('[loginFlow] typed pass using', s);
          break;
        }
      } catch (e) { /* ignore */ }
    }

    // submit via form button or enter key
    const submitButtons = ['button[type="submit"]', 'input[type="submit"]', '#wp-submit', 'button[name="login"]', 'button'];
