Patch 1 — tickets unsaved-change / beforeunload handler (add to tickets JS)
- Place in the theme/plugin JS bundled for the tickets page (example path below). The code tracks form changes, enables a beforeunload confirmation only when the form is dirty, and disables it on successful submit.

```javascript
// filepath: assets/js/page-tickets.js
// ...existing code...
(function () {
  // Simple dirty-check + guarded beforeunload for the Tickets ACF form
  const form = document.querySelector('#page-tickets-form'); // adjust selector to real form ID/class
  if (!form) return;

  let isDirty = false;

  // Mark dirty on input/select/textarea change
  form.addEventListener('input', () => { isDirty = true; });

  // If there are file uploaders handled separately, listen to change as well
  form.querySelectorAll('input[type="file"]').forEach(f => {
    f.addEventListener('change', () => { isDirty = true; });
  });

  // Disable beforeunload when submitting via the form
  form.addEventListener('submit', () => { isDirty = false; });

  // Guarded beforeunload handler
  function beforeUnloadHandler(e) {
    if (!isDirty) return;
    const confirmationMessage = 'יש שינויים לא שמורים. האם לאפשר יציאה?'; // localized text
    (e || window.event).returnValue = confirmationMessage;
    return confirmationMessage;
  }

  // Attach/detach on focus/blur of page or when toggling create/history panel
  window.addEventListener('beforeunload', beforeUnloadHandler);

  // If your existing controller opens/closes the create panel, ensure it toggles isDirty appropriately:
  // Example: document.querySelector('#tickets-create-open').addEventListener('click', () => { isDirty = false; });
})();
```

