        const duration = timing ? timing.receiveHeadersEnd - timing.startTime : -1;
        xhrMetrics.push({
          url,
          method: request.method(),
          status: response.status(),
          duration,
        });
        if (duration > 500) {
          console.warn(`🐢 Slow XHR [${request.method()}] ${url} → ${Math.round(duration)}ms`);
