        timestamp: new Date().toISOString(),
      });
    }

    return foundEmptyMsg;

  } catch (err) {
    console.warn('⚠️ ticketEmptyStateFlow failed:', err.message);
    if (context.shouldExport) {
      addMetric({
        flow: 'ticketEmptyStateFlow',
        emptyMsgFound: false,
        error: err.message,
        timestamp: new Date().toISOString(),
      });
    }
    return false;
  }
};

