        if (btn) { await btn.click().catch(()=>{}); clicked = true; console.log('[loginFlow] clicked', sel); break; }
      } catch (e) { /* ignore */ }
    }
    if (!clicked) {
      // fallback: press Enter in password field
      try { await page.keyboard.press('Enter'); } catch (e) {}
    }

    // Wait for a robust logged-in signal. Prioritize selectors that indicate a logged in user.
    const loggedInSelectors = [
      'body.logged-in',         // common WP class
      '.bb-profile',            // BuddyBoss profile indicator
      '.bb-user-avatar',        // BuddyBoss avatar
      '.logout',                // visible logout link/button
      '#bp-login'               // fallback
    ];

    const start = Date.now();
    let loggedIn = false;
    while (Date.now() - start < waitMs) {
      for (const sel of loggedInSelectors) {
        try {
          if (await page.$(sel)) { loggedIn = true; console.log('[loginFlow] detected logged-in selector', sel); break; }
        } catch (e) {}
      }
      if (loggedIn) break;
      // Also check for URL change away from login page (common after successful login)
      const curr = page.url();
      if (!curr.includes('/custom-login') && !curr.includes('/wp-login.php')) { loggedIn = true; console.log('[loginFlow] detected URL change to', curr); break; }
      await page.waitForTimeout(500);
    }

    await page.screenshot({ path: `${outputDir}/after_login.png` }).catch(()=>{});
    if (!loggedIn) {
      console.warn('[loginFlow] did not detect logged-in state within', waitMs, 'ms');
      // continue but report non-ok so orchestrator can decide
      return { ok: false, error: 'login timeout', meta: { typedUser, typedPass } };
    }

    return { ok: true };
  } catch (err) {
    await page.screenshot({ path: `${outputDir}/login_error.png` }).catch(()=>{});
    return { ok: false, error: err.message };
  }
}

